  const adjustedReturns = excessReturns.map((r) => Math.max(r, 1e-3));
  const scores = assets.map((a3, i) => adjustedReturns[i] / (a3.volatility * a3.volatility));
  const totalScore = scores.reduce((a3, b2) => a3 + b2, 0);
  const weights = totalScore > 0 ? scores.map((s) => s / totalScore) : assets.map(() => 1 / n6);
  let portfolioVariance = 0;
  for (let i = 0; i < n6; i++) {
    for (let j = 0; j < n6; j++) {
      const corr = correlations[i]?.[j] ?? (i === j ? 1 : 0.3);
      portfolioVariance += weights[i] * weights[j] * assets[i].volatility * assets[j].volatility * corr;
    }
  }
  const portfolioReturn = assets.reduce((sum, a3, i) => sum + weights[i] * a3.expectedReturn, 0);
  const portfolioVol = Math.sqrt(portfolioVariance);
