function getAvailableBenchmarks() {
  return Object.entries(BENCHMARK_DATA).map(([symbol7, data]) => ({
    symbol: symbol7,
    name: data.name
  }));
}
function calculateAlpha(portfolioReturn, benchmarkReturn) {
  return portfolioReturn - benchmarkReturn;
}
function calculateTrackingError(portfolioReturns, benchmarkReturns) {
  if (portfolioReturns.length !== benchmarkReturns.length || portfolioReturns.length === 0) {
    return 0;
  }
  const diffs = portfolioReturns.map((p2, i) => p2 - benchmarkReturns[i]);
  const mean = diffs.reduce((a3, b2) => a3 + b2, 0) / diffs.length;
  const variance = diffs.reduce((sum, d2) => sum + Math.pow(d2 - mean, 2), 0) / diffs.length;
  return Math.sqrt(variance);
}
function calculateInformationRatio(alpha, trackingError) {
  if (trackingError === 0) return 0;
  return alpha / trackingError;
}
function compareToBenchmarks(portfolioPnlPercent, benchmarkSymbols) {
  const results = [];
  for (const symbol7 of benchmarkSymbols) {
    const data = BENCHMARK_DATA[symbol7];
    if (!data) continue;
    const alpha = calculateAlpha(portfolioPnlPercent, data.approxAnnualReturn * 100);
    results.push({
      symbol: symbol7,
      name: data.name,
      return: data.approxAnnualReturn * 100,
      alpha
    });
  }
  results.sort((a3, b2) => b2.alpha - a3.alpha);
  const winner = results[0] ? results[0].alpha >= 0 ? `Portfolio outperformed ${results[0].name} by ${results[0].alpha.toFixed(2)}%` : `Portfolio underperformed ${results[0].name} by ${Math.abs(results[0].alpha).toFixed(2)}%` : "No benchmark data available";
  const summary = `Portfolio: ${portfolioPnlPercent >= 0 ? "+" : ""}${portfolioPnlPercent.toFixed(2)}% | ${results.map((r) => `${r.name}: ${r.return >= 0 ? "+" : ""}${r.return.toFixed(1)}% (\u03B1 ${r.alpha >= 0 ? "+" : ""}${r.alpha.toFixed(2)}%)`).join(" | ")}`;
  return {
    portfolioPnlPercent,
    benchmarks: results,
    winner,
    summary
  };
}
