init_agent();
async function* runAgentStream(params) {
  const startTime = Date.now();
  let output = "";
  let toolCalls = 0;
  const agent = await Agent.create({
    model: params.model,
    maxIterations: params.maxIterations,
    signal: params.signal
  });
  const result = agent.run(params.query);
  let finalResult = {
    output: "",
    toolCalls: 0,
    iterations: 0,
    totalTime: 0
  };
  for await (const event of result) {
    yield event;
    switch (event.type) {
      case "tool_start":
        toolCalls++;
        break;
      case "done":
        output = event.answer;
        finalResult = {
          output,
          toolCalls,
          iterations: event.iterations,
          totalTime: Date.now() - startTime
        };
        break;
    }
  }
  return finalResult;
}

